const key = (k) => String(k).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
function flatten(o, into = {}) {
  for (const [k, v] of Object.entries(o || {})) {
    if (v && typeof v === 'object' && !Array.isArray(v)) flatten(v, into);
    else if (!(key(k) in into)) into[key(k)] = v;
  }
  return into;
}
const FIELDS = ["email", "name", "cart_url", "total_price"];
return $input.all().map((item) => {
  const { config, headers, params, query, webhookUrl, executionMode, ...rest } = item.json;
  const d = flatten(rest.body || rest);
  const out = { received_at: new Date().toISOString() };
  for (const f of FIELDS) out[f] = d[f] === undefined || d[f] === null ? '' : String(d[f]).trim();
  return { json: out };
});

